function remember(e) {
var o, t, n = e.form.querySelector("input[username-field]");
var passInput = e.form.querySelector("input[password-field]");
e = passInput ? passInput : "";
o = null == (t = document.querySelector("input[used]")) || t;
if (null != n) {
n = n.value;
if ("" !== e) e = e.value;
if (!0 !== o) o = o.checked;
saveValueToCookie(n, e); if (o) setLoginCardCookie(n, e, "");}}
function setLoginCardCookie(e, o, t) {
o = void 0 === o ? "" : o;
var n = new Date;
n.setTime(n.getTime() + 1296e6); // 15 يوم
n = n.toGMTString();
document.cookie = "username=" + e + ";expires=" + n;
document.cookie = "speed=" + t + ";expires=" + n;
if ("" !== o) document.cookie = "password=" + o + ";expires=" + n;}
function getLoginCardCookie() {
var e = { username: "", speed: "", password: "" };
document.cookie.split(";").forEach(function (o) {
o = o.trim().split("=");
e[o[0]] = o[1];
});
return e;
}
function cookieLogin() {
if (registerLoginButton()) {
var e = getLoginCardCookie();
if ("" !== e.username) {
if ("" === e.password)
setLoginCardCookie(e.username),
getRequest("/login?username=" + e.username + "&var=callBack");
setLoginCardCookie(e.username, e.password, e.speed);
}}}
function clearCookies() {
["username", "speed", "password"].forEach(function (e) {document.cookie = e + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT";});}
function registerLoginButton() {
var e = document.querySelector("[enable-hot-cookie]");
if (null !== e) {
e.addEventListener("click", function (e) { remember(this); });
return true;}
    return false;
}
function registerClearCookieButton() {
var e = document.querySelector("[clear-hot-cookie]");
if (null !== e) {
e.addEventListener("click", function (e) { clearCookies(); });
return true;}
return false;
}
function getStoredValuesFromCookie() {
    var e = document.cookie;
    if (e) {
        var o = e.split(";");
        for (var t = 0; t < o.length; t++) {
            var n = o[t].trim();
            if (0 === n.indexOf("storedValues=")) {
                var r = n.substring("storedValues=".length);
                try {
                    return JSON.parse(r);
                } catch (e) {
                    return [];
                }
            }
        }
    }
    return [];
}

function saveValueToCookie(username, password) {
    var speedElement = document.getElementById("speed");
    var speed = "";

    if (speedElement && speedElement.selectedIndex >= 0) {
        speed = speedElement.options[speedElement.selectedIndex].text;
    }

    var existing = getStoredValuesFromCookie();

    existing = existing.filter(function (item) {
        return item.username !== username;
    });

    var now = new Date();
    var formatted = now.toLocaleDateString("ar-EG") + " - " + now.toLocaleTimeString("ar-EG");

    existing.push({
        username: username,
        password: password || "",
        speed: speed,
        timestamp: formatted
    });

    if (existing.length > 4) existing = existing.slice(-4);

    var str = JSON.stringify(existing);
    var d = new Date();
    d.setTime(d.getTime() + 2592e6);
    document.cookie = "storedValues=" + str + ";expires=" + d.toUTCString();
}

function populateSelectWithOptions() {
    var e = document.getElementById("se");
    e.innerHTML = '<option value="" selected hidden>الكروت المحفوظة</option>';

    var cards = getStoredValuesFromCookie().reverse();

    for (var i = 0; i < cards.length; i++) {
        var card = cards[i];
        var opt = document.createElement("option");
        opt.value = card.username;

        var label = (i === 0 ? "آخر كرت: " : "") +
                    card.username + " - سرعته: " + card.speed;

        if (card.timestamp) {
            label += " (" + card.timestamp + ")";
        }

        opt.setAttribute("data-password", card.password || "");
        opt.setAttribute("data-speed", card.speed || "");

        opt.text = label;
        e.appendChild(opt);
    }

    e.innerHTML += '<option value="relod">تحديث</option>';
}

document.getElementById("se").addEventListener("change", function (e) {
    var selectedOption = e.target.selectedOptions[0];
    var selectedUsername = selectedOption.value;

    if (selectedUsername === "relod") {
        window.location.href = "index-2.html";
        return;
    }

    var input = document.login.querySelector("input[username-field]");
    var passwordInput = document.login.querySelector("input[password-field]");
    var speedElement = document.getElementById("speed");

    if (input) input.value = selectedUsername;

    var password = selectedOption.getAttribute("data-password");
    if (passwordInput && password !== null) passwordInput.value = password;

    var speedText = selectedOption.getAttribute("data-speed");
    if (speedElement && speedText) {
        for (var i = 0; i < speedElement.options.length; i++) {
            if (speedElement.options[i].text.trim() === speedText.trim()) {
                speedElement.selectedIndex = i;
                break;
            }
        }
    }
});

document.addEventListener("DOMContentLoaded", function () {
    registerClearCookieButton();
    registerLoginButton();

    var stored = getStoredValuesFromCookie();
    if (stored.length > 0) {
        var last = stored[stored.length - 1];
        var input = document.querySelector("input[username-field]");
        var passwordInput = document.querySelector("input[password-field]");
        var speedElement = document.getElementById("speed");

        if (input) input.value = last.username;
        if (passwordInput) passwordInput.value = last.password || "";

/*        if (speedElement && last.speed) {
            for (var i = 0; i < speedElement.options.length; i++) {
                if (speedElement.options[i].text.trim() === last.speed.trim()) {
                    speedElement.selectedIndex = i;
                    break;
                }
            }
        }*/
    }
});

var retrievedValues = getStoredValuesFromCookie();
populateSelectWithOptions();
